#ifndef REINSIRK_INTEGER_SIEVE_DEFINED
#define REINSIRK_INTEGER_SIEVE_DEFINED
// Sieve(maxn): maxn>=0の最小素因数表・昇順素数列をO(maxn)時間・領域で作る。0,1の最小素因数は0。
// コピーは独立、コピー代入は強保証。ムーブ元は空となりmax_value()=-1。
// swap(other): 表と素数列をO(1)で交換する。
// max_value(): 表の上限を返す。is_prime(x): 0<=x<=max_value()の素数判定をO(1)で返す。
// factorize(x): 1<=x<=max_value()^2の素因数と指数のmapを返す。x=1は空の表でも許す。
// divisors(x), sorted_divisors(x): factorizeと同じ前提で全約数を返す。後者だけ昇順。
// euler_of_divisors(x): factorizeと同じ前提で各約数dからphi(d)へのmapを返す。
// mobius_table(), GenerateMoebiusFunctionTable(): O(maxn)でmu表を返す。mu[0]=0,mu[1]=1。
// totient_table(): O(maxn)でphi表を返す。phi[0]=0,phi[1]=1。
// enumerate_kth_pows<Mint>(k,nmax): 0<=nmax<=max_value(),k>=0でn^kの表。0^0=1。
// べき乗表はO(nmax+pi(nmax)log(k+1))時間・O(nmax)領域。公開配列を変更せず使う。
struct Sieve {
    std::vector<int> min_factor;
    std::vector<int> primes;

    explicit Sieve(int maxn) : min_factor(table_size(maxn)) {
        const std::size_t limit = min_factor.size();
        for (std::size_t i = 2; i < limit; ++i) {
            if (min_factor[i] == 0) {
                min_factor[i] = static_cast<int>(i);
                primes.push_back(static_cast<int>(i));
            }
            const int first = min_factor[i];
            for (const int p : primes) {
                const std::uint64_t next = static_cast<std::uint64_t>(i) *
                                           static_cast<std::uint64_t>(p);
                if (next >= limit) break;
                min_factor[static_cast<std::size_t>(next)] = p;
                if (p == first) break;
            }
        }
    }

    Sieve(const Sieve&) = default;
    Sieve& operator=(const Sieve& other) {
        if (this != &other) {
            Sieve copy(other);
            swap(copy);
        }
        return *this;
    }
    Sieve(Sieve&& other) noexcept
        : min_factor(std::move(other.min_factor)), primes(std::move(other.primes)) {
        other.min_factor.clear();
        other.primes.clear();
    }
    Sieve& operator=(Sieve&& other) noexcept {
        if (this != &other) {
            min_factor = std::move(other.min_factor);
            primes = std::move(other.primes);
            other.min_factor.clear();
            other.primes.clear();
        }
        return *this;
    }

    void swap(Sieve& other) noexcept {
        min_factor.swap(other.min_factor);
        primes.swap(other.primes);
    }

    int max_value() const noexcept {
        return min_factor.empty() ? -1 : static_cast<int>(min_factor.size() - 1);
    }

    template <std::integral Int>
    bool is_prime(Int x) const {
#ifndef SKIP_RUNTIME_CHECKS
        if constexpr (std::signed_integral<Int>) {
            if (x < 0) throw std::out_of_range("Sieve::is_prime: negative input");
        }
        if (static_cast<std::uint64_t>(x) >= min_factor.size()) {
            throw std::out_of_range("Sieve::is_prime: input outside table");
        }
#endif
        const std::uint64_t value = static_cast<std::uint64_t>(x);
        return value >= 2 && static_cast<std::uint64_t>(min_factor[static_cast<std::size_t>(value)]) == value;
    }

    template <std::integral Int>
    std::map<Int, int> factorize(Int x) const {
#ifndef SKIP_RUNTIME_CHECKS
        if (x < 1) throw std::invalid_argument("Sieve::factorize: input must be positive");
#endif
        std::uint64_t rest = static_cast<std::uint64_t>(x);
        std::map<Int, int> result;
        if (rest == 1) return result;
        const int maximum = max_value();
#ifndef SKIP_RUNTIME_CHECKS
        if (maximum < 1 || rest > static_cast<std::uint64_t>(maximum) *
                                     static_cast<std::uint64_t>(maximum)) {
            throw std::out_of_range("Sieve::factorize: input exceeds table limit squared");
        }
#endif
        const std::uint64_t bound = static_cast<std::uint64_t>(maximum);
        if (rest > bound) {
            for (const int prime : primes) {
                const std::uint64_t p = static_cast<std::uint64_t>(prime);
                if (p * p > rest) break;
                if (rest % p == 0) {
                    int exponent = 0;
                    do {
                        rest /= p;
                        ++exponent;
                    } while (rest % p == 0);
                    result.emplace(static_cast<Int>(prime), exponent);
                    if (rest <= bound) break;
                }
            }
            if (rest > bound) {
                result.emplace(static_cast<Int>(rest), 1);
                return result;
            }
        }
        while (rest > 1) {
            const int prime = min_factor[static_cast<std::size_t>(rest)];
            int exponent = 0;
            do {
                rest /= static_cast<std::uint64_t>(prime);
                ++exponent;
            } while (rest > 1 && min_factor[static_cast<std::size_t>(rest)] == prime);
            result.emplace(static_cast<Int>(prime), exponent);
        }
        return result;
    }

    template <std::integral Int>
    std::vector<Int> divisors(Int x) const {
        const auto factors = factorize(x);
        std::vector<Int> result{static_cast<Int>(1)};
        for (const auto& [prime, exponent] : factors) {
            const std::size_t previous = result.size();
            reserve_multiple(result, static_cast<std::size_t>(exponent) + 1);
            std::uint64_t power = 1;
            for (int e = 1; e <= exponent; ++e) {
                power *= static_cast<std::uint64_t>(prime);
                for (std::size_t i = 0; i < previous; ++i) {
                    result.push_back(static_cast<Int>(static_cast<std::uint64_t>(result[i]) * power));
                }
            }
        }
        return result;
    }

    template <std::integral Int>
    std::vector<Int> sorted_divisors(Int x) const {
        auto result = divisors(x);
        std::sort(result.begin(), result.end());
        return result;
    }

    template <std::integral Int>
    std::map<Int, Int> euler_of_divisors(Int x) const {
        const auto factors = factorize(x);
        std::vector<std::pair<Int, Int>> values{{static_cast<Int>(1), static_cast<Int>(1)}};
        for (const auto& [prime, exponent] : factors) {
            const std::size_t previous = values.size();
            reserve_multiple(values, static_cast<std::size_t>(exponent) + 1);
            const std::uint64_t p = static_cast<std::uint64_t>(prime);
            std::uint64_t power = 1;
            std::uint64_t phi_power = p - 1;
            for (int e = 1; e <= exponent; ++e) {
                power *= p;
                for (std::size_t i = 0; i < previous; ++i) {
                    values.emplace_back(
                        static_cast<Int>(static_cast<std::uint64_t>(values[i].first) * power),
                        static_cast<Int>(static_cast<std::uint64_t>(values[i].second) * phi_power));
                }
                if (e < exponent) phi_power *= p;
            }
        }
        return std::map<Int, Int>(values.begin(), values.end());
    }

    std::vector<int> mobius_table() const {
        std::vector<int> result(min_factor.size());
        if (result.size() > 1) result[1] = 1;
        for (std::size_t i = 2; i < result.size(); ++i) {
            const int p = min_factor[i];
            const std::size_t quotient = i / static_cast<std::size_t>(p);
            result[i] = min_factor[quotient] == p ? 0 : -result[quotient];
        }
        return result;
    }

    std::vector<int> GenerateMoebiusFunctionTable() const {
        return mobius_table();
    }

    std::vector<int> totient_table() const {
        std::vector<int> result(min_factor.size());
        if (result.size() > 1) result[1] = 1;
        for (std::size_t i = 2; i < result.size(); ++i) {
            const int p = min_factor[i];
            const std::size_t quotient = i / static_cast<std::size_t>(p);
            result[i] = result[quotient] * (min_factor[quotient] == p ? p : p - 1);
        }
        return result;
    }

    template <class MODINT>
    std::vector<MODINT> enumerate_kth_pows(std::int64_t k, int nmax) const {
#ifndef SKIP_RUNTIME_CHECKS
        if (k < 0) throw std::invalid_argument("Sieve::enumerate_kth_pows: negative exponent");
        if (nmax < 0 || nmax > max_value()) {
            throw std::out_of_range("Sieve::enumerate_kth_pows: input outside table");
        }
#endif
        const std::size_t count = table_size(nmax);
        if (count > std::vector<MODINT>().max_size()) {
            throw std::length_error("Sieve::enumerate_kth_pows: table too large");
        }
        if (k == 0) return std::vector<MODINT>(count, MODINT(1));
        std::vector<MODINT> result(count);
        if (count > 0) result[0] = MODINT(0);
        if (count > 1) result[1] = MODINT(1);
        for (std::size_t i = 2; i < count; ++i) {
            const int p = min_factor[i];
            if (static_cast<std::size_t>(p) == i) {
                result[i] = MODINT(p).pow(k);
            } else {
                result[i] = result[static_cast<std::size_t>(p)] *
                            result[i / static_cast<std::size_t>(p)];
            }
        }
        return result;
    }

private:
    static std::size_t table_size(int maximum) {
#ifndef SKIP_RUNTIME_CHECKS
        if (maximum < 0) throw std::invalid_argument("Sieve: negative table limit");
#endif
        const std::uint64_t count = static_cast<std::uint64_t>(maximum) + 1;
        if (count > std::vector<int>().max_size()) {
            throw std::length_error("Sieve: table too large");
        }
        return static_cast<std::size_t>(count);
    }

    template <class T>
    static void reserve_multiple(std::vector<T>& values, std::size_t multiplier) {
        if (multiplier > values.max_size() / values.size()) {
            throw std::length_error("Sieve: divisor table too large");
        }
        values.reserve(values.size() * multiplier);
    }
};
#endif

#ifndef REINSIRK_INTEGER_TRANSFORM_DETAIL_DEFINED
#define REINSIRK_INTEGER_TRANSFORM_DETAIL_DEFINED
struct ReinsirkIntegerTransform {
    // 素数pについて、指数を1段進める／戻す伝播を行う。
    template <bool ToMultiples, bool Subtract, class T>
    static void propagate(std::vector<T>& a, const std::vector<int>& primes) {
        if (a.size() <= 2) return;
        const std::size_t upper = a.size() - 1;
        for (const int value : primes) {
            const auto p = static_cast<std::size_t>(value);
            if (p > upper) break;
            const auto count = upper / p;
            if constexpr (ToMultiples != Subtract) {
                for (std::size_t from = 1, to = p; from <= count; ++from, to += p) {
                    if constexpr (ToMultiples) a[to] += a[from];
                    else a[from] -= a[to];
                }
            } else {
                for (std::size_t from = count, to = count * p; from; --from, to -= p) {
                    if constexpr (ToMultiples) a[to] -= a[from];
                    else a[from] += a[to];
                }
            }
        }
    }
    static std::vector<int> primes_for(std::size_t size) {
        if (size <= 2) return {};
        if (size - 1 > static_cast<std::size_t>(std::numeric_limits<int>::max()))
            throw std::length_error("integer transform: maximum exceeds INT_MAX");
        const auto upper = size - 1;
        std::vector<unsigned char> marked(upper / 2 + 1);
        std::vector<int> answer{2};
        for (std::size_t p = 3; p <= upper; p += 2) {
            if (marked[p / 2]) continue;
            answer.push_back(static_cast<int>(p));
            if (p <= upper / p)
                for (std::size_t k = p * p / 2; k < marked.size(); k += p) marked[k] = 1;
        }
        return answer;
    }
#ifndef SKIP_RUNTIME_CHECKS
    static void require_sieve(std::size_t size, const Sieve& sieve) {
        if (size && (sieve.max_value() < 0 || size - 1 > static_cast<std::size_t>(sieve.max_value())))
            throw std::out_of_range("integer transform: sieve too small");
    }
    static void require_same_size(std::size_t a, std::size_t b) {
        if (a != b) throw std::invalid_argument("integer convolution: different lengths");
    }
#endif
};
#endif

// 正の添字の4変換。f[0]は不変、空配列も可。時間O(n log log n)。
// multiple_zeta(f): f[d]=sum_{d|k} f[k]へ更新する。
// multiple_moebius(f): 倍数ゼータ変換を元に戻す。
// divisor_zeta(f): f[k]=sum_{d|k} f[d]へ更新する。
// divisor_moebius(f): 約数ゼータ変換を元に戻す。
// 各(f,sieve)版: sieve.max_value()>=f.size()-1の素数表を再利用し、追加領域O(1)。
// 各(f)版: 素数表も作る。f.size()-1<=INT_MAX、追加領域O(n)。
#ifndef REINSIRK_MULTIPLE_ZETA_DEFINED
#define REINSIRK_MULTIPLE_ZETA_DEFINED
template <class T> void multiple_zeta(std::vector<T>& f, const Sieve& sieve) {
#ifndef SKIP_RUNTIME_CHECKS
    ReinsirkIntegerTransform::require_sieve(f.size(), sieve);
#endif
    ReinsirkIntegerTransform::propagate<false, false>(f, sieve.primes);
}
template <class T> void multiple_zeta(std::vector<T>& f) {
    ReinsirkIntegerTransform::propagate<false, false>(f, ReinsirkIntegerTransform::primes_for(f.size()));
}
#endif
#ifndef REINSIRK_MULTIPLE_MOEBIUS_DEFINED
#define REINSIRK_MULTIPLE_MOEBIUS_DEFINED
template <class T> void multiple_moebius(std::vector<T>& f, const Sieve& sieve) {
#ifndef SKIP_RUNTIME_CHECKS
    ReinsirkIntegerTransform::require_sieve(f.size(), sieve);
#endif
    ReinsirkIntegerTransform::propagate<false, true>(f, sieve.primes);
}
template <class T> void multiple_moebius(std::vector<T>& f) {
    ReinsirkIntegerTransform::propagate<false, true>(f, ReinsirkIntegerTransform::primes_for(f.size()));
}
#endif
